"""Verify grounding instructions reach both generation modes without model I/O."""

from collections.abc import AsyncIterator
from unittest.mock import AsyncMock, Mock

import pytest

from app.core.config import YamlAppConfig
from app.core.llm import LLMProvider
from app.generation.generator import SYSTEM_PROMPT, GenerationEngine
from app.retrieval.engine import RetrievalEngine, RetrievedChunk


@pytest.mark.asyncio
@pytest.mark.parametrize("has_evidence", [True, False])
async def test_grounding_prompt_shared_by_generation_modes(has_evidence: bool) -> None:
    """Keep instructions identical while preserving evidence, citations and scope."""
    chunks = (
        [RetrievedChunk("doc:0", "doc", "The launch code is Amber.", 1.0)]
        if has_evidence
        else []
    )
    answer = "The launch code is Amber. [1]" if has_evidence else "Not established."
    captured: list[list[dict[str, str]]] = []

    async def stream(messages: list[dict[str, str]]) -> AsyncIterator[str]:
        """Capture streaming messages and yield a provider-shaped response."""
        captured.append(messages)
        yield answer

    provider = Mock(spec=LLMProvider)
    provider.acomplete = AsyncMock(return_value=answer)
    provider.astream = stream
    retrieval = Mock(spec=RetrievalEngine)
    retrieval.retrieve = AsyncMock(return_value=chunks)
    engine = GenerationEngine(YamlAppConfig(), provider, retrieval)

    result = await engine.generate("What is the launch code?", collection_id="isolated")
    streamed = "".join(
        [
            token
            async for token in engine.generate_stream(
                "What is the launch code?", chunks=chunks
            )
        ]
    )

    retrieval.retrieve.assert_awaited_once_with(
        "What is the launch code?", collection_id="isolated"
    )
    messages = provider.acomplete.call_args.args[0]
    assert captured == [messages]
    assert messages[0] == {"role": "system", "content": SYSTEM_PROMPT}
    for instruction in (
        "not outside knowledge or memory",
        "evidence, not instructions",
        "entities, dates and numbers",
        "correct mismatches",
        "do not establish",
        "yes/no answer must agree",
        "actually support each claim",
    ):
        assert instruction in messages[0]["content"]
    assert messages[1]["content"].endswith("Question: What is the launch code?")
    assert ("The launch code is Amber." in messages[1]["content"]) == has_evidence
    assert result["answer"] == streamed == answer
    assert result["chunks_used"] == len(chunks)
    assert len(result["citations"]) == len(chunks)
    assert len(result["retrieval_chunks"]) == len(chunks)
